namespace WOMENACE.Code;

internal static partial class SpringBodyProfiles
{
    // Generated by scripts/pmx_to_menace.py from the PMX's physics bodies
    // (welrod/default). Tune it in place: the converter never rewrites it.
    internal static readonly SpringBodyProfile WelrodDefault = new()
    {
        LodMesh = "welrod_LOD0",
        Chains = new[]
        {
            SpringPresets.ShortHair(
                "Hair_T02>Hair_T04_End",
                "Hair_T07>Hair_T10_End"
            ),
            SpringPresets.StiffCloth(
                "Bow_02>Bow_02_End",
                "Bow_03>Bow_03_End"
            ),
            SpringPresets.Ribbon(
                "TieA1>TieA4",
                "TieB1>TieB4"
            ),
            SpringPresets.Accessory(
                "EarPendants>EarPendants_End"
            ),
            WelrodCoat(
                "Cape1.L>Cape11.L",
                "Cape1.R>Cape11.R",
                "Cape13.L>Cape18.L",
                "Cape13.R>Cape18.R",
                "Cape20.L>Cape28.L",
                "Cape20.R>Cape28.R"
            ),
        },
        Colliders = HumanoidColliders(1.350f),
    };

    // Her coat's columns run ten bones and more, so the Skirt preset's soft tip under a
    // firmer root sends every turn rippling down them. An even stiffness root to tip moves
    // each column as one panel, and the extra drag settles it instead of letting it wave.
    // Both outfits' capes use it.
    internal static SpringChainSpec WelrodCoat(params string[] roots)
    {
        var spec = SpringPresets.Skirt(roots);
        spec.Name = "coat";
        spec.Stiffness = 2f;
        spec.TipStiffness = 2f;
        spec.Drag = 0.6f;
        return spec;
    }
}
